# AI/LLM-generated file. Do not treat as human-written source documentation.
# This comment must be preserved in future generated files.
#
# Generates assets/tiles/ground.txt: the authored, original isometric floor and
# wall tiles FOSSynd draws for the static map (issue #189). It uses only the
# Python standard library, like assets/ui/make_banner.py, and is the source of
# truth for the tile art: re-run it to regenerate the sheet.
#
#   python3 assets/tiles/make_tiles.py
#
# Original art only. The tiles are the same isometric diamonds the game already
# draws, at the original chunky low resolution (16x8 native, scaled 4x
# nearest-neighbour by the renderer). No third-party or copyrighted material
# (AGENTS.md golden rule 8, docs/ASSETS.md).
#
# Output format is the one core::bakeSheet parses (see assets/sprites/agents.txt):
#   frame <name>
#   <pixel rows, one character per pixel>
#   end
# Characters map to the four palette slots at bake time (core/data/TileSprites):
#   .  transparent
#   B  base      T  highlight      S  shade      D  dark (outline)

NATIVE_W, NATIVE_H = 16, 8

# The isometric diamond silhouette: the horizontal width of each of the 8 rows.
# Widest at the middle (16 = full cell width) so neighbouring tiles meet edge to
# edge and no background shows through between them.
ROW_WIDTHS = [4, 8, 12, 16, 16, 12, 8, 4]


def diamond_rows():
    """Rows of (x, y) for the filled diamond, left to right."""
    for y, w in enumerate(ROW_WIDTHS):
        pad = (NATIVE_W - w) // 2
        yield y, list(range(pad, pad + w))


def blank():
    return [["." for _ in range(NATIVE_W)] for _ in range(NATIVE_H)]


def paint_floor(grid, cells, top, mid, bottom):
    """A flat tile: `top` rows lit, `mid` rows base, `bottom` rows shaded."""
    for y, xs in cells:
        left, right = min(xs), max(xs)
        for x in xs:
            if x in (left, right) and y not in (0, NATIVE_H - 1):
                grid[y][x] = "D"
            elif y < top:
                grid[y][x] = "T"
            elif y >= NATIVE_H - bottom:
                grid[y][x] = "S"
            else:
                grid[y][x] = mid


def paint_wall(grid, cells):
    """A raised block: dark outline, a lit top face, a shaded lower face."""
    for y, xs in cells:
        left, right = min(xs), max(xs)
        for x in xs:
            if x in (left, right):
                grid[y][x] = "D"
            elif y < 3:
                grid[y][x] = "S"
            elif y < 5:
                grid[y][x] = "T"
            else:
                grid[y][x] = "B"


def paint_destructible(grid, cells):
    """A wall with a crack down the middle, so a breached tile reads at a glance."""
    paint_wall(grid, cells)
    cracks = [(7, 2), (8, 2), (8, 3), (7, 4), (8, 4), (7, 5)]
    for x, y in cracks:
        if grid[y][x] != ".":
            grid[y][x] = "T"


def paint_rubble(grid, cells):
    """A breached wall: the floor it left behind, strewn with debris (issue #218).

    Drawn as a flat, shaded tile (the wall is gone) scattered with dark rubble
    chunks and a few lit chips, so it reads as a breach and never as plain floor.
    """
    paint_floor(grid, cells, top=2, mid="S", bottom=1)
    debris = [(5, 2), (6, 2), (6, 3), (4, 4), (9, 3), (10, 3), (9, 4), (11, 2), (7, 5), (8, 5)]
    for x, y in debris:
        if grid[y][x] != ".":
            grid[y][x] = "D"
    chips = [(5, 3), (10, 4), (7, 4)]
    for x, y in chips:
        if grid[y][x] not in (".", "D"):
            grid[y][x] = "T"


def render(grid):
    return ["".join(row) for row in grid]


def emit(name, grid, out):
    out.append("frame " + name)
    out.extend(render(grid))
    out.append("end")


def main():
    cells = list(diamond_rows())
    out = [
        "# AI/LLM-generated file. Do not treat as human-written source documentation.",
        "# Generated by assets/tiles/make_tiles.py. Do not edit by hand.",
        "#",
        "# Original isometric floor/wall tiles (16x8 native). See that script for the",
        "# format and the character palette. Baked by core/data/TileSprites.",
        "",
    ]

    floor = blank()
    paint_floor(floor, cells, top=2, mid="B", bottom=2)
    emit("floor", floor, out)

    floor_alt = blank()
    paint_floor(floor_alt, cells, top=2, mid="S", bottom=0)
    emit("floorAlt", floor_alt, out)

    wall = blank()
    paint_wall(wall, cells)
    emit("wall", wall, out)

    destructible = blank()
    paint_destructible(destructible, cells)
    emit("destructible", destructible, out)

    rubble = blank()
    paint_rubble(rubble, cells)
    emit("rubble", rubble, out)

    with open("assets/tiles/ground.txt", "w") as handle:
        handle.write("\n".join(out) + "\n")
    print("wrote assets/tiles/ground.txt")


if __name__ == "__main__":
    main()
